sysdrills/17-client-data-layer/01-fetch-.solution:
function lastFinish(fetches, waitsOn) {
  const finish = [];
  fetches.forEach((fetch, i) => {
    const parent = waitsOn(fetch);
    const start = parent < 0 ? 0 : finish[parent];
    finish[i] = start + fetch.ms;
  });
  return Math.max(...finish);
}

export function readyMs(fetches) {
  return lastFinish(fetches, (fetch) => fetch.after);
}

export function hoistedMs(fetches) {
  return lastFinish(fetches, (fetch) => (fetch.needsParent ? fetch.after : -1));
}

