sysdrills/17-client-data-layer/02-query-.solution:
function isStale(ageMs, staleTimeMs) {
  return ageMs >= staleTimeMs;
}

export function onMount(ageMs, staleTimeMs, unobservedMs, gcTimeMs) {
  if (unobservedMs >= gcTimeMs) return 'load';
  return isStale(ageMs, staleTimeMs) ? 'serve-and-refetch' : 'serve';
}

export function focusRefetches(queries, staleTimeMs) {
  return queries.filter((query) => query.observers > 0 && isStale(query.ageMs, staleTimeMs)).length;
}

