sysdrills/17-client-data-layer/03-visibi.solution:
export function pollQps(clients, visiblePermille, intervalSec) {
  return (clients * visiblePermille) / 1000 / intervalSec;
}

export function emptyPollPermille(intervalSec, changeEverySec) {
  if (intervalSec >= changeEverySec) return 0;
  return ((changeEverySec - intervalSec) * 1000) / changeEverySec;
}

